/**
 * jQuery Simple Equal Heights per row
 * Version 1.0.1 - registers synchronously so dependent scripts can use it safely.
 */
(function ($) {
    "use strict";

    $.fn.equalHeights = function (options) {
        var settings = $.extend({
            innerItem: false,
            parent: this.parent(),
            perRow: true
        }, options);
        var items = this;

        function setHeight(elements, height, innerItem, rowParent) {
            if (!innerItem) {
                $(elements).height(height);
                return;
            }

            if (height === "auto") {
                $(elements).find(innerItem).height(height);
                return;
            }

            $(elements).find(innerItem).each(function () {
                var availableHeight = height;
                $(this).siblings().each(function () {
                    availableHeight -= $(this).outerHeight();
                });

                var current = this;
                do {
                    current = $(current).parent();
                    availableHeight -= parseInt(current.css("padding-top"), 10) || 0;
                    availableHeight -= parseInt(current.css("padding-bottom"), 10) || 0;
                } while (!current.is(rowParent));

                $(this).height(availableHeight);
            });
        }

        $(settings.parent).each(function () {
            var row = [];
            var rowWidth = 0;
            var rowHeight = 0;
            var parent = this;
            var currentItems = settings.parent.length > 1 ? $(this).find(items) : items;

            setHeight(currentItems, "auto", settings.innerItem);
            $(currentItems).each(function () {
                var itemWidth = $(this).outerWidth(true);
                var itemHeight = $(this).height();

                if (settings.perRow && row.length && itemWidth + rowWidth > $(parent).width()) {
                    setHeight(row, rowHeight, settings.innerItem, parent);
                    row = [];
                    rowWidth = 0;
                    rowHeight = 0;
                }

                row.push(this);
                rowWidth += itemWidth;
                rowHeight = Math.max(rowHeight, itemHeight);
            });

            if (row.length) setHeight(row, rowHeight, settings.innerItem, parent);
        });

        return this;
    };

    $(function () {
        $("[data-equalheights]").each(function () {
            var selector = $(this).attr("data-equalheights");
            var items = $(this).find(selector);
            items.equalHeights();
            $(window).on("resize", function () { items.equalHeights(); });
        });
    });
})(jQuery);
